ALTER TABLE "compensatory_request" DROP CONSTRAINT "compensatory_request_classification_pair";--> statement-breakpoint
ALTER TABLE "compensatory_request" ADD CONSTRAINT "compensatory_request_classification_pair" CHECK (("compensatory_request"."requested_date" is null and "compensatory_request"."requested_minutes" is null and "compensatory_request"."classified_at" is null and "compensatory_request"."classified_by_user_id" is null) or ("compensatory_request"."requested_date" ~ '^\d{4}-\d{2}-\d{2}$' and "compensatory_request"."requested_minutes" > 0 and "compensatory_request"."classified_at" is not null and "compensatory_request"."classified_by_user_id" is not null) or ("compensatory_request"."submission_source" = 'public' and "compensatory_request"."requested_date" ~ '^\d{4}-\d{2}-\d{2}$' and "compensatory_request"."requested_minutes" > 0 and "compensatory_request"."classified_at" is null and "compensatory_request"."classified_by_user_id" is null));